<section class="page-banner"><div class="container"><a class="back-link" href="<?= e(url('clubs')) ?>">← Clubs & societies</a><div class="club-heading"><div class="club-big-icon"><?= e(icon_for($club['category'])) ?></div><div><div class="section-label"><?= e($club['category']) ?> · <?= e($club['faculty']) ?></div><h1><?= e($club['name']) ?></h1><p><?= (int)$club['members'] ?> approved members<?= $club['leader_name']?' · Club leader: '.e($club['leader_name']):'' ?></p></div></div></div></section>
<section class="section container"><div class="columns-main"><div><div class="card panel"><h2>About this community</h2><p class="preserve-text"><?= e($club['description']) ?></p><?php if(!empty($club['contact_email'])): ?><p><strong>Club contact:</strong> <a href="mailto:<?= e($club['contact_email']) ?>"><?= e($club['contact_email']) ?></a></p><?php endif; ?></div><div class="section-heading slim"><h2>Club events</h2></div><?php if($events): ?><div class="cards-grid two-cards"><?php foreach($events as $eventItem){$eventItem['club_name']=$club['name'];require dirname(__DIR__).'/partials/event_card.php';}?></div><?php else:?><div class="empty-state">No approved events for this club yet.</div><?php endif; ?><div class="section-heading slim"><h2>Latest announcements</h2></div><?php if($notices): ?><div class="card panel"><?php foreach($notices as $n): ?><article class="stack-item"><h3><?= e($n['title']) ?></h3><p class="preserve-text"><?= e($n['body']) ?></p><small><?= e($n['author']) ?> · <?= e(pretty_date($n['created_at'],'d M Y')) ?></small></article><?php endforeach;?></div><?php else:?><div class="empty-state">No announcements have been posted.</div><?php endif; ?></div>
<aside><div class="card panel sticky-panel"><div class="section-label">GET INVOLVED</div><h3>Become part of the community</h3><p>Ask to join this society and follow club activities.</p>
<?php if(!user()): ?><a href="<?= e(url('login')) ?>" class="btn btn-primary btn-block">Sign in to join</a><?php elseif((int)$club['leader_user_id']===(int)user()['id']): ?><a href="<?= e(url('leader',['club_id'=>$club['id']])) ?>" class="btn btn-primary btn-block">Manage this club</a>
<?php elseif(user()['role']==='admin'): ?><a href="<?= e(url('admin/club/form',['id'=>$club['id']])) ?>" class="btn btn-primary btn-block">Manage club details</a>
<?php elseif($membership && $membership['status']==='approved'): ?><?= status_pill('approved') ?><p>You are an approved member.</p><form method="post" action="<?= e(url('club/leave')) ?>" data-confirm="Leave this club?"><?= csrf_field() ?><input type="hidden" name="club_id" value="<?= (int)$club['id'] ?>"><button class="btn btn-outline btn-block">Leave club</button></form>
<?php elseif($membership && $membership['status']==='pending'): ?><?= status_pill('pending') ?><p>Your membership request is awaiting review.</p><form method="post" action="<?= e(url('club/leave')) ?>"><?= csrf_field() ?><input type="hidden" name="club_id" value="<?= (int)$club['id'] ?>"><button class="btn btn-outline btn-block">Withdraw request</button></form>
<?php else: ?><form method="post" action="<?= e(url('club/join')) ?>"><?= csrf_field() ?><input type="hidden" name="club_id" value="<?= (int)$club['id'] ?>"><button class="btn btn-primary btn-block">Request membership →</button></form><?php endif; ?></div></aside></div></section>
